import{_ as s,o as a,c as t,a5 as r}from"./chunks/framework.DrDMl0tG.js";const n="/assets/sensors_cpp.QC5IHf1C.png",m=JSON.parse('{"title":"Server Example: Sensor Suite","description":"","frontmatter":{},"headers":[],"relativePath":"sections/examples/server/sensor_suite.md","filePath":"sections/examples/server/sensor_suite.md"}'),i={name:"sections/examples/server/sensor_suite.md"};function o(l,e,h,d,c,p){return a(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="server-example-sensor-suite" tabindex="-1">Server Example: Sensor Suite <a class="header-anchor" href="#server-example-sensor-suite" aria-label="Permalink to &quot;Server Example: Sensor Suite&quot;">​</a></h1><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>Demonstrates the RGB camera, depth camera, IMU, and LiDAR sensors on ANYmal, including depth-to-point-cloud conversion and point-cloud visualization. It is the main reference for the sensor APIs; see <a href="./../../Sensors.html">Sensors</a>.</p><h2 id="screenshot" tabindex="-1">Screenshot <a class="header-anchor" href="#screenshot" aria-label="Permalink to &quot;Screenshot&quot;">​</a></h2><p><img src="'+n+`" alt="sensor_suite example"></p><h2 id="target" tabindex="-1">Target <a class="header-anchor" href="#target" aria-label="Permalink to &quot;Target&quot;">​</a></h2><p>CMake target: <code>sensor_suite</code>. The source is <code>examples/src/server/sensor_suite.cpp</code>.</p><h2 id="run" tabindex="-1">Run <a class="header-anchor" href="#run" aria-label="Permalink to &quot;Run&quot;">​</a></h2><p>Start the viewer, then run the build-tree example:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Terminal 1</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./build-examples/examples/rayrai_tcp_viewer</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Terminal 2</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./build-examples/examples/sensor_suite</span></span></code></pre></div><p>On Windows, run <code>sensor_suite.exe</code> instead. The example uses RaisimServer on port 8080.</p><h2 id="details" tabindex="-1">Details <a class="header-anchor" href="#details" aria-label="Permalink to &quot;Details&quot;">​</a></h2><ul><li>Loads <code>anymal_c/urdf/anymal_sensored.urdf</code>, which carries front and rear RGB/depth cameras, an IMU, and a spinning LiDAR.</li><li>Configures the RGB and depth cameras with <code>MeasurementSource::MANUAL</code>. The TCP viewer renders these camera frames on request, returns BGRA and metric depth buffers to <code>RaisimServer</code>, and shows previews in the <strong>Sensors</strong> tab of the selected ANYmal. The source includes a commented-out line that switches the front depth camera to RaiSim CPU depth.</li><li>Select the ANYmal, open <strong>Sensors</strong>, and use <strong>Show frustum</strong> to inspect the camera pose and range in the main scene.</li><li>Converts the front depth array to 3D points with <code>DepthCamera::depthToPointCloud</code> and reads the LiDAR scan.</li><li>Streams the latest LiDAR scan as a point cloud and two marker spheres through <code>RaisimServer</code>.</li></ul>`,13)])])}const _=s(i,[["render",o]]);export{m as __pageData,_ as default};
